import "testing"

func TestIsPalindrome(t *testing.T) {
	cases := []struct {
		s    string
		want bool
	}{
		{"A man, a plan, a canal: Panama", true},
		{"race a car", false},
		{"", true},
		{" ", true},
		{".,", true},
		{"0P", false},
		{"aa", true},
		{"ab", false},
	}
	for _, c := range cases {
		if got := isPalindrome(c.s); got != c.want {
			t.Fatalf("isPalindrome(%q) = %v, want %v", c.s, got, c.want)
		}
	}
